/*
 * Standalone semantic harness for the candidate _sctp_make_chunk().
 *
 * It #includes the function body EXTRACTED VERBATIM from the candidate
 * worktree (validation/func_extracted.h) and supplies minimal mocks for the
 * kernel primitives. It is NOT a kernel build; it exercises the control flow
 * and boundary arithmetic of the changed code with the same macros/types the
 * target kernel defines (WORD_ROUND, SCTP_MAX_CHUNK_LEN, sctp_chunkhdr_t).
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef uint8_t  __u8;
typedef uint16_t __u16;
typedef uint16_t __be16;
typedef uint32_t __u32;

#define GFP_ATOMIC 0
#define WORD_ROUND(s) (((s) + 3) & ~3)
enum { SCTP_MAX_CHUNK_LEN = ((1 << 16) - sizeof(__u32)) };

struct sctp_chunkhdr {
	__u8	type;
	__u8	flags;
	__be16	length;
};
typedef struct sctp_chunkhdr sctp_chunkhdr_t;

struct sock { int dummy; };
struct sctp_association { struct { struct sock *sk; } base; };

struct sk_buff {
	unsigned char buf[1 << 18];
	size_t len;
};

struct sctp_chunk {
	sctp_chunkhdr_t *chunk_hdr;
	__u8 *chunk_end;
	int auth;
};

static unsigned long g_last_alloc = (unsigned long)-1;
static unsigned long g_alloc_calls = 0;

static void *alloc_skb(size_t size, int gfp)
{
	struct sk_buff *s = calloc(1, sizeof(*s));
	(void)gfp;
	g_last_alloc = (unsigned long)size;
	g_alloc_calls++;
	return s;
}

static void *skb_put(struct sk_buff *skb, unsigned int len)
{
	unsigned char *p = skb->buf + skb->len;
	skb->len += len;
	return p;
}

static void kfree_skb(struct sk_buff *skb) { free(skb); }

static int sctp_auth_send_cid(__u8 type, const struct sctp_association *asoc)
{
	(void)type; (void)asoc;
	return 0;
}

static struct sctp_chunk *sctp_chunkify(struct sk_buff *skb,
					const struct sctp_association *asoc,
					struct sock *sk)
{
	(void)skb; (void)asoc; (void)sk;
	return calloc(1, sizeof(struct sctp_chunk));
}

static __u16 htons(__u16 x) { return x; }

#include "func_extracted.h"

/* The pre-fix (vulnerable) body, for contrast. */
static struct sctp_chunk *_sctp_make_chunk_vuln(const struct sctp_association *asoc,
						__u8 type, __u8 flags, int paylen)
{
	struct sctp_chunk *retval;
	sctp_chunkhdr_t *chunk_hdr;
	struct sk_buff *skb;
	struct sock *sk;

	/* No need to allocate LL here, as this is only a chunk. */
	skb = alloc_skb(WORD_ROUND(sizeof(sctp_chunkhdr_t) + paylen),
			GFP_ATOMIC);
	if (!skb)
		goto nodata;

	chunk_hdr = (sctp_chunkhdr_t *)skb_put(skb, sizeof(sctp_chunkhdr_t));
	chunk_hdr->type	  = type;
	chunk_hdr->flags  = flags;
	chunk_hdr->length = htons(sizeof(sctp_chunkhdr_t));

	sk = asoc ? asoc->base.sk : NULL;
	retval = sctp_chunkify(skb, asoc, sk);
	if (!retval) {
		kfree_skb(skb);
		goto nodata;
	}
	retval->chunk_hdr = chunk_hdr;
	retval->chunk_end = ((__u8 *)chunk_hdr) + sizeof(struct sctp_chunkhdr);
	if (sctp_auth_send_cid(type, asoc))
		retval->auth = 1;
	return retval;
nodata:
	return NULL;
}

static int failures;

static void check(const char *label, int paylen)
{
	unsigned long expected = WORD_ROUND(sizeof(sctp_chunkhdr_t) + (unsigned long)paylen);
	int over = (int)expected > SCTP_MAX_CHUNK_LEN;
	struct sctp_chunk *c;

	/* fixed function */
	g_last_alloc = (unsigned long)-1;
	g_alloc_calls = 0;
	c = _sctp_make_chunk(NULL, 0, 0, paylen);
	{
		int ok;
		if (over)
			ok = (c == NULL && g_alloc_calls == 0);
		else
			ok = (c != NULL && g_alloc_calls == 1 &&
			      g_last_alloc == expected);
		printf("%-28s paylen=%-8d padded=%-8lu limit=%-6d over=%d "
		       "fixed=%-6s alloc=%-8lu calls=%lu -> %s\n",
		       label, paylen, expected, SCTP_MAX_CHUNK_LEN, over,
		       c ? "chunk" : "NULL", g_last_alloc, g_alloc_calls,
		       ok ? "PASS" : "FAIL");
		if (!ok)
			failures++;
		free(c);
	}

	/* vulnerable function */
	g_last_alloc = (unsigned long)-1;
	g_alloc_calls = 0;
	c = _sctp_make_chunk_vuln(NULL, 0, 0, paylen);
	if (over) {
		/* Demonstrates the missing bound: allocates an over-limit size. */
		printf("%-28s paylen=%-8d vulnerable: alloc=%-8lu (over limit, no rejection) retval=%s\n",
		       label, paylen, g_last_alloc, c ? "chunk" : "NULL");
	}
	free(c);
}

int main(void)
{
	printf("SCTP_MAX_CHUNK_LEN=%d sizeof(hdr)=%zu\n\n",
	       SCTP_MAX_CHUNK_LEN, sizeof(sctp_chunkhdr_t));

	check("positive/normal", 100);
	check("positive/max-data", 65524);
	check("boundary/accept", 65525);
	check("negative/over-by-1", 65529);
	check("negative/upstream-crash", 120152);
	check("negative/negative-paylen", -1);

	printf("\n%s (failures=%d)\n", failures ? "RESULT: FAIL" : "RESULT: PASS", failures);
	return failures ? 1 : 0;
